import java.util.Arrays; import java.util.List; public class Test { public static void main(String[] args) { List<Double> values = Arrays.asList(2.0, 4.0, 6.0); double mean = values.stream().mapToDouble(Double::doubleValue).average().orElseThrow(); double sum = 0.0; for (double value : values) { double difference = value - mean; sum += difference * difference; } System.out.println("Sum: " + sum); System.out.println("Result: " + (sum / (values.size() - 1))); } }
